// OLED SSD1306 — matn va oddiy grafik
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>
Adafruit_SSD1306 ekran(128, 64, &Wire, -1);

int qiymat = 0;

void setup() {
  Serial.begin(9600);
  if (!ekran.begin(SSD1306_SWITCHCAPVCC, 0x3C)) {
    Serial.println("OLED topilmadi! Manzilni (0x3C/0x3D) tekshiring.");
    while (true);
  }
  ekran.clearDisplay();
  ekran.setTextColor(SSD1306_WHITE);
}

void loop() {
  ekran.clearDisplay();

  ekran.setTextSize(1);
  ekran.setCursor(0, 0);
  ekran.print("Harorat:");

  ekran.setTextSize(2);
  ekran.setCursor(0, 16);
  ekran.print(qiymat);
  ekran.print(" C");

  // pastda progress chizigʻi
  ekran.drawRect(0, 50, 128, 10, SSD1306_WHITE);
  ekran.fillRect(0, 50, map(qiymat, 0, 50, 0, 128), 10, SSD1306_WHITE);

  ekran.display();          // ENG MUHIM QATOR — usiz ekran boʻsh qoladi

  qiymat = (qiymat + 1) % 51;
  delay(200);
}

