  int yangi = 0;
  if (q > XAVF)        yangi = 2;
  else if (q > DIQQAT) yangi = 1;

  if (yangi != daraja) {
    daraja = yangi;

    digitalWrite(LED_SARIQ, daraja == 1);
    digitalWrite(LED_QIZIL, daraja == 2);

    if (daraja == 2) {
      bot.sendMessage(CHAT_ID, "XAVF! Qiymat: " + String(q) + "\nDarhol tekshiring.", "");
